> Can you share commands how to reproduce this please? Then I can have a look.

My code is long. But you can reproduce it by following simple lines:

```
#include <mavsdk/mavsdk.h>
#include <mavsdk/system.h>
#include <mavsdk/plugins/camera/camera.h>
int main(int argc, char** argv)
{
	std::shared_ptr<mavsdk::System> sys;
	auto cam = std::make_shared<mavsdk::Camera>(sys);
	return 0;
}
```

This doesn't look correct:
```
std::shared_ptr<mavsdk::System> sys;
```

Can you try like this instead?
```
#include <chrono>
#include <iostream>
#include <memory>
#include <thread>
#include <mavsdk/mavsdk.h>
#include <mavsdk/system.h>
#include <mavsdk/plugins/camera/camera.h>

int main(int argc, char** argv)
{
    mavsdk::Mavsdk mavsdk;
    mavsdk.add_udp_connection();    

    // Wait for system to connect via heartbeat.
    std::this_thread::sleep_for(std::chrono::seconds(2));
    
    if (mavsdk.systems().empty()) {
        std::cout << "No system found\n";
        return -1;
    }

    auto system = mavsdk.systems().at(0);

    if (!system->has_camera()) {
        std::cout << "No camera found\n";
        return -1;
    }

    auto camera = mavsdk::Camera{system};

    return 0;
}
```

